// Indexé par CLÉ DE SPRITE STATIQUE du jeu (le draw connaît cette clé) → infos d'anim.
const ANIM_BY_SK = (() => {
  const out = {};
  for (const cle in ANIM_DATA) {
    const meta = ANIM_META[cle];
    if (!meta) continue;
    // Clé statique correspondante : 1er candidat présent dans SPRITE_DATA (même logique que
    // buildingSpriteKey), pour que frame 0 = le sprite statique réel.
    const sk = [cle, 'bat_' + cle, cle + '_v1'].find(c => SPRITE_DATA[c]) || cle;
    out[sk] = {
      cle,
      frames: meta.frames,
      fw: meta.fw,
      fh: meta.fh,
      fps: meta.fps
    };
  }
  // La tour aéroréfrigérante a ses DEUX clés statiques dans SPRITE_DATA (tour_… ET bat_tour_…) :
  // le draw passe par buildingSpriteKey (priorité bat_…) alors que l'index ci-dessus retient la
  // 1re candidate (tour_…) → alias explicite pour que l'anim soit trouvée au rendu.
  if (out['tour_aerorefrigerante']) out['bat_tour_aerorefrigerante'] = out['tour_aerorefrigerante'];
  return out;
})();
const animImgCache = {};
function animImg(cle) {
  const cached = animImgCache[cle];
  if (cached !== undefined) return spriteUsable(cached) ? cached : null;
  const data = ANIM_DATA[cle];
  if (!data) {
    animImgCache[cle] = null;
    return null;
  }
  const img = new Image();
  animImgCache[cle] = img;
  img.onload = () => {
    if (spriteOnReady) spriteOnReady();
  };
  img.onerror = () => {
    animImgCache[cle] = null;
  };
  img.src = data;
  return spriteUsable(img) ? img : null;
}
// Vide les caches d'images (statiques + anims) → tout est RE-DÉCODÉ depuis les data-URL au
// prochain dessin. Indispensable au retour d'arrière-plan : la WebView jette les bitmaps décodés,
// et sans purge les entrées restent des Image mortes (rien ne se dessine plus jamais).
// `spriteOnReady` redessine au fil des décodages, donc l'image revient progressivement.
function resetSpriteCaches() {
  let n = 0;
  for (const k in spriteImgCache) { delete spriteImgCache[k]; n++; }
  for (const k in animImgCache) { delete animImgCache[k]; n++; }
  return n;
}
