function buildingConnectsCarrier(buildingId, carrier) {
  const ck = buildingId + '|' + carrier;
  if (_connectsCache[ck] !== undefined) return _connectsCache[ck];
  const b = BUILDINGS[buildingId];
  let res = false;
  if (b) {
    if (b.id === 'port' || buildingId === 'port' || b.fixed && b.name === 'Port') {
      res = carrier === 'road' || carrier === 'pipe';
    } else if (carrier === 'wire') {
      // Connects to power grid if it draws or feeds energy.
      res = (b.power || 0) > 0 || !!b.sigmoid || !!b.randomP || !!b.nuclear || !!b.antenna || b.accumulator || b.outputs && b.outputs.energie_kw != null || (() => {
        for (const k in b.inputs || {}) if (carrierOf(k) === 'wire') return true;
        for (const k in b.outputs || {}) if (k !== 'energie_kw' && carrierOf(k) === 'wire') return true;
        return false;
      })();
    } else if (b.driller && carrier === 'road') {
      // FOREUSE : sa sortie (pierre, débit selon le cercle) est INJECTÉE AU TICK, elle n'est pas déclarée
      // dans la def → sans ce cas, la route ne dessinait aucune branche vers elle et la foreuse
      // semblait « non connectée » alors qu'elle évacuait bien sa pierre (retour testeur).
      res = true;
    } else {
      // road / pipe: has any input or output carried by this type
      for (const k in b.inputs || {}) if (carrierOf(k) === carrier) {
        res = true;
        break;
      }
      if (!res) for (const k in b.outputs || {}) if (k !== 'energie_kw' && carrierOf(k) === carrier) {
        res = true;
        break;
      }
      // nuclear plant has no declared I/O but uses road (materials) ; le refroidissement
      // passe désormais par la chaleur (conduit), plus par le tuyau.
      if (!res && b.nuclear) res = carrier === 'road';
      // 14.30 — CONDUIT : aucune ressource déclarée ne le porte (la chaleur n'est pas une
      // ressource de pool) → il n'était branché nulle part et le conduit ne traversait AUCUN
      // bâtiment, contrairement au câble et au tuyau. Se raccordent : les sources (heatCap,
      // dont la centrale) et les tours aéroréfrigérantes.
      if (!res && carrier === 'conduit') res = !!b.heatCap || !!b.tour;
      // 14.36 — REFROIDISSEUR : son fluide est choisi au runtime (COOLER_DEF), il n'a donc AUCUN
      // `inputs` statique → sans ce cas il ne dessinerait aucun raccord tuyau et ne ferait pas
      // PONT, alors que la tour qu'il remplace le fait (elle a `eau` en dur). Même esprit que la
      // foreuse et sa route. Volontairement indépendant du mode COURANT : changer de fluide ne doit
      // JAMAIS couper en deux un tuyau qui traversait le bâtiment.
      if (!res && b.cooler && carrier === 'pipe') res = true;
    }
  }
  _connectsCache[ck] = res;
  return res;
}
// Bitmask (N=1, E=2, S=4, O=8) des côtés où un voisin se raccorde à l'un des
// `carriers` donnés (un réseau a un seul carrier, une jonction en couple deux).
// Sert à amincir réseaux ET jonctions sans casser les raccords : on n'insère la
// marge que sur les côtés sans connexion.
function netConnectMask(tiles, r, c, carriers, junctionAxis, infraOnly) {
  let mask = 0;
  const nb = [[-1, 0, 1], [0, 1, 2], [1, 0, 4], [0, -1, 8]];
  for (const [dr, dc, bit] of nb) {
    let nt = tiles[r + dr] && tiles[r + dr][c + dc];
    if (nt && nt.occupied) {
      nt = tiles[nt.occupied.r] && tiles[nt.occupied.r][nt.occupied.c];
    }
    if (!nt || !nt.building) continue;
    const nid = nt.building.id;
    const ndef = BUILDINGS[nid];
    let connects = false;
    for (const carrier of carriers) {
      if (nid === carrier) {
        connects = true; // même infra réseau
      } else if (ndef && ndef.kind === 'junction' && ndef.junction && ndef.junction.indexOf(carrier) !== -1) {
        // Jonction qui porte ce type. Avec `junctionAxis` (sprites d'infra), on exige en plus
        // qu'elle transmette VERS cette tuile (le long de son axe, règle 13.18) — sinon la tuile
        // dessinait une branche vers une jonction à laquelle elle n'est PAS raccordée. Le flag est
        // opt-in car junctionAxisH (orientation d'une jonction) passe par ici : l'activer là
        // créerait une récursion entre jonctions adjacentes.
        connects = !junctionAxis || junctionDirOk(tiles, r + dr, c + dc, ndef, carrier, -dr, -dc);
      } else if (!infraOnly && ndef && ndef.kind !== 'infra' && ndef.kind !== 'junction') {
        // 14.21 — `infraOnly` EXCLUT les bâtiments. Indispensable pour DÉDUIRE L'AXE d'une jonction
        // (junctionAxisH) : un bâtiment est un CONSOMMATEUR en bout de ligne, il ne dit RIEN du sens
        // dans lequel le réseau court. En le comptant, une simple pompe/tour/raffineur posé à l'EST
        // d'une jonction faisait croire que le tuyau allait EST-OUEST, ce qui BASCULAIT l'axe et
        // COUPAIT le tracé NORD-SUD qui la traversait (45 configurations sur 128 au balayage).
        // Partout ailleurs (sprites, stubs) les bâtiments comptent toujours : on veut bien dessiner
        // une branche vers eux.
        connects = buildingConnectsCarrier(nid, carrier); // bâtiment desservi
      }
      if (connects) break;
    }
    if (connects) mask |= bit;
  }
  return mask;
}
