  const half = Math.hypot(cam.cssW / 2, cam.cssH / 2);
  const d = Math.hypot(dx, dy) / half;         // 0 centré · 1 dans un coin · > 1 hors champ
  const prox = Math.max(0, Math.min(1, 1 - d / 2));            // éteint à deux rayons de viewport
  const zf = Math.max(0, Math.min(1, (cam.zoom - MIN_ZOOM) / (MAX_ZOOM - MIN_ZOOM)));
