const tierForfait = id => (TIER_STEP[id] && TIER_STEP[id].forfait) || (BUILDINGS[id] && BUILDINGS[id].cost) || {};

// ── Fours à arc unifiés (sélecteur multi-sortie PAR BÂTIMENT) ────────────────
// input : ressource consommée (débit fixe inRate × 2^upgrade, quel que soit le mode).
// modes : par sortie → out (part de sortie, base) + powBase/powAmp (sigmoïde de conso base, kW :
// plancher = powBase, pic = powBase + powAmp, ratio plancher→pic = 8).
