  for (const k of keys) {
    const f = w[k] / sum, m = def.modes[k];
    if (f > 0) outputs[k] = (outputs[k] || 0) + f * m.out;
    pbase += f * m.powBase; pamp += f * m.powAmp;
  }
  const inputs = { [def.input]: def.inRate };
  if (def.extraIn) for (const k in def.extraIn) inputs[k] = (inputs[k] || 0) + def.extraIn[k];
