        const dcBits = Math.min(palier, Math.max(1, (dcTile.building.upgrade || 0) + 1));
        co.code = pickFlavorCode(palier, true); // exceptions autorisées : leptons 000/111
        co.dcCode = pickFlavorCode(dcBits, false); // jamais 000/111 → aucun cas ambigu
        co.round = (co.round || 0) + 1; // une manche = UN verdict (cf. vanne)
