function techNodesOrdered(game) {
  return TECH_NODES.slice().sort((a, b) => {
    const ca = game.techTree.nodes[a.id - 1].status === 'confirmed' ? 1 : 0;
    const cb = game.techTree.nodes[b.id - 1].status === 'confirmed' ? 1 : 0;
    return ca - cb || a.id - b.id;
  });
}
