  if (g.elevatorRepaired == null) g.elevatorRepaired = false;
  if (g.elevatorLevel == null) g.elevatorLevel = 0;
  if (ELEVATOR_MODES.indexOf(g.elevatorMode) === -1) g.elevatorMode = 'priority';
