  // `isl` optionnel : île dont on lit/débite le port (défaut = île courante). Sert au forage,
  // payé depuis le PORT DE L'ÎLE 6 (le souterrain, île 7, n'a pas de port — cf. rapport §4.3).
  function missingFor(cost, isl) {
    const res = portPool(gameRef.current, isl);
    const miss = [];
    for (const k in cost) {
      const need = cost[k] - (res[k] || 0);
      // Arrondi à l'entier SUPÉRIEUR (les stocks sont fractionnaires en interne) + notation
      // « port » — fini les toasts « manque 352.49999999999994 ».
      if (need > 0) miss.push(`${fmtPort(Math.ceil(need))} ${RES_SHORT[k]}`);
    }
    return miss;
  }
  // 14.62 — Rend la réserve TENUE par « Demander au port » (cfg.askPrev) dès que la ressource est
  // réellement DÉPENSÉE : la demande est comblée, la réserve n'a plus lieu d'être. Relâcher plus tôt
  // (à l'ARRIVÉE de la marchandise) rouvrirait la fenêtre qu'on ferme — le bateau réexpédierait en
  // aval la matière à peine débarquée.
