    const hasA = tileCarrier === typeA || adjacentNetworks(g, isl, r, c, typeA).length > 0;
    const hasB = tileCarrier === typeB || adjacentNetworks(g, isl, r, c, typeB).length > 0;
    // Auto-pose du porteur manquant (« la route de l'autre côté ») perpendiculairement
