      const vert = carries(tiles[r - 1] && tiles[r - 1][c], present) || carries(tiles[r + 1] && tiles[r + 1][c], present);
      const horiz = carries(tiles[r] && tiles[r][c - 1], present) || carries(tiles[r] && tiles[r][c + 1], present);
      const axisKnown = vert !== horiz;
