    bumpHud();
    markDirty();
    scheduleSave();
    SFX.play('junction');
    if (verbose) showToast(`✓ ${b.name}` + (Object.keys(cost).length ? ` — ${formatCost(cost)}` : ''), 'var(--green)');
    return true;
