  // Badges « infos » en bas à gauche de la case : [efficacité %][niveau] (gauche→droite).
  // Le % d'efficacité n'apparaît qu'en cas de déficit (eff < ~99,5 %, y compris 0 % à l'arrêt),
  // désactivable via g.ui.showDeficitPct ; le numéro de niveau (≥2) via g.ui.showLevels.
  // Numéro de niveau réduit (0.22 au lieu de 0.30) pour laisser place au pourcentage.
  function drawInfoBadges(ctx, x, y, W, H, tile, upg, eff) {
    if (tile < 16) return;
    const ui = gameRef.current.ui;
    const showLv = ui.showLevels !== false && upg > 0;
    const deficit = eff != null && eff < 0.995;
    const showPct = ui.showDeficitPct !== false && deficit;
    if (!showLv && !showPct) return;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    // Taille de base ~0.16 (intermédiaire) × le multiplicateur commun réglable (Options, 0,5→2).
    const sc = Math.max(0.5, Math.min(2, ui.badgeScale || 1));
    const fs = Math.max(6, Math.round(tile * 0.16 * sc));
    const pad = Math.max(1, tile * 0.038 * sc);
    const gap = Math.max(1, tile * 0.045 * sc);
    const segH = fs + pad * 2;
    let bx = x + Math.max(1, tile * 0.04);
    const by = y + H - segH - Math.max(1, tile * 0.04);
    const drawSeg = (txt, bg, fg) => {
      ctx.font = `700 ${fs}px "DM Mono",monospace`;
      const bw = ctx.measureText(txt).width + pad * 2;
      roundRectPath(ctx, bx, by, bw, segH, Math.max(1, tile * 0.045 * sc));
      ctx.fillStyle = bg;
      ctx.fill();
      ctx.fillStyle = fg;
      ctx.fillText(txt, bx + pad, by + pad);
      bx += bw + gap;
    };
    if (showPct) {
      const pct = Math.round(Math.max(0, Math.min(1, eff)) * 100);
      drawSeg(pct + '%', 'rgba(40,20,6,.80)', pct <= 0 ? '#ff9a8f' : '#ffd27f');
    }
    if (showLv) drawSeg(String(upg + 1), 'rgba(13,13,26,.66)', '#9ee29f');
  }
  // Petite icône de déficit / panne, en HAUT À DROITE de la case (taille réduite).
  // Désactivable via g.ui.showDeficitSprite. `reason` choisit le sprite d'état.
  function drawDeficitIcon(ctx, x, y, W, H, tile, reason) {
    if (gameRef.current.ui.showDeficitSprite === false) return;
    // Éteint par un ACTIONNEUR logique : la pastille `ui_pause_logique` (coin haut-gauche) dit déjà
    // « en pause », et elle est plus précise. Sans ce garde, la tuile portait DEUX pastilles de
    // pause côte à côte (retour testeur « double badge pause »).
    if (reason === 'logic') return;
    const s = Math.max(9, Math.min(W, H) * 0.40);
    const pad = Math.max(1, tile * 0.04);
    const bx = x + W - s - pad,
      by = y + pad;
    if (!drawSprite(ctx, statusSpriteKey(reason), bx, by, s, s)) {
      // Fallback (PNG absent) : pastille colorée selon la cause.
      ctx.fillStyle = reason === 'input' ? 'rgba(255,170,40,.9)' : 'rgba(255,80,60,.9)';
      roundRectPath(ctx, bx, by, s, s, s * 0.25);
      ctx.fill();
    }
  }
  // Barre de TRAVAUX d'un bâtiment souterrain : progression de la matière qui descend par
  // l'élévateur + décompte (s restantes au débit courant, ⏸ si rien ne descend). Sert au fantôme
