    const c0 = Math.max(0, Math.floor((0 - ox) / tile));
    const c1 = Math.min(def.cols - 1, Math.floor((cam.cssW - ox) / tile));
    const r0 = Math.max(0, Math.floor((0 - oy) / tile));
    const r1 = Math.min(def.rows - 1, Math.floor((cam.cssH - oy) / tile));
    const isl = g.currentIsland;
