        //      TRAVERSANT étalé sur la machine ;
        //  (c) les JONCTIONS sont reconnues (règle d'axe 13.18, cf. junctionDirOk) — sans ça, un
        //      joueur raccordant via une jonction ne voyait aucun raccord alors que le lien
        //      mécanique existait.
        // Ordre tuyau → câble : le câble passe au-dessus, même convention que les stubs de bâtiment.
        for (const scar of ['pipe', 'wire']) {
          for (const [ddr, ddc, bit] of [[-1, 0, 1], [0, 1, 2], [1, 0, 4], [0, -1, 8]]) {
            let nt2 = tiles[r + ddr] && tiles[r + ddr][c + ddc];
            if (nt2 && nt2.occupied) nt2 = tiles[nt2.occupied.r] && tiles[nt2.occupied.r][nt2.occupied.c];
            if (!nt2 || !nt2.building) continue;
            const nd2 = BUILDINGS[nt2.building.id];
            const isJ2 = !!(nd2 && nd2.kind === 'junction' && nd2.junction && nd2.junction.indexOf(scar) !== -1 && junctionDirOk(tiles, r + ddr, c + ddc, nd2, scar, -ddr, -ddc));
            if (nt2.building.id !== scar && !isJ2) continue;
            // Pour une JONCTION le networkId du porteur vit dans netIds[carrier] (networkId est null)
            // — sinon le raccord se dessinerait toujours en V1.
            const snid = isJ2 ? nt2.netIds && nt2.netIds[scar] : nt2.networkId;
            const sn = g.networks[isl] && g.networks[isl][snid];
            drawSprite(ctx, NET_PREFIX[scar] + '_v' + (sn && sn.unlimited ? 4 : Math.min(sn && sn.level || 1, 3)) + '_' + NET_MASK_SUFFIX[bit], x, y, tile, tile);
          }
        }
        const isCol = (rr, cc) => tiles[rr] && tiles[rr][cc] && tiles[rr][cc].terrain === 'collider';
        // Bloc collisionneur = 3 tuiles de large × 2 de haut (sprite officiel bat_collisionneur_ruine
