        // d'adjacence. Motif : la cle normale sort de coastIsCoast(), pas de t.terrain - une tuile
        // comblee que le joueur finit par entourer de terre serait redessinee en 'land' et le
        // remblai disparaitrait. Une cle par ile suffit donc, la ou l'adjacence en aurait demande 12.
        // Ile 7 exclue : la branche isTun passe avant (cf. A1).
        const baseKey = isTun ? (ring7 ? 'tile_i7_land_clair' : 'tile_i7_land') : isFilledTile(t) ? 'tile_i' + isl + '_remblai' : 'tile_i' + isl + '_' + (coastIsCoast(tiles, def, r, c) ? 'coast' : 'land');
        if (!drawTileAnim(ctx, baseKey, x, y, tile, r, c) && !drawSprite(ctx, baseKey, x, y, tile, tile)) {
          const tk = 'tile_i' + isl + '_' + t.terrain;
          if (!drawSprite(ctx, tk, x, y, tile, tile)) {
            ctx.fillStyle = TERRAIN_COLORS[t.terrain];
            ctx.fillRect(x, y, tile, tile);
          }
        }
        // Pas de triangle de transition « littoral » sous terre (île 7).
