        const suf = ['n', 's', 'o', 'e'][dir] || 'n';
        const sst = lg.logicOut ? '1' : '0';
        const dbase = lbd.logicJunction ? 'logic_jonction_NS_EO' : lbd.logicValve ? 'logic_vanne_collisionneur' : lbd.logicGate ? 'logic_porte_' + lbd.logicGate : lbd.logicSource ? 'logic_senseur' : lbd.logicSink ? 'logic_actionneur' : lbd.logicMultiSource ? 'logic_emetteur_alpha' : null;
        // Chaîne de repli par dispositif. La JONCTION porte DEUX signaux (axes NS et EO) : son art
